"""
Offline mock of a tender bid wizard with a cascading position configurator. Invented labels and values, worded
differently from the real portal on purpose. Usage: python mock.py PORT
"""
import html
import json
import random
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import parse_qs

ITEMS = {"1.10": "Lifting cylinder", "1.2": "Clamp cylinder", "1.3": "Spare cylinder"}
ORDER = ["1.2", "1.3", "1.10"]
random.seed(4)
DIAMETERS = ["10", "100", "12", "125", "16", "8"]
LENGTHS = {"12": ["300", "30", "500"], "125": ["50", "500"], "_": ["40", "400"]}
SEALS = [("std", "Standard"), ("vit", "Viton"), ("none", "Without seal kit")]
ARTICLES = {("12", "300", "std"): [("AB-1200", "AB-1200 · 250 bar"), ("AB-120", "AB-120 · 160 bar")],
            ("125", "50", "none"): [("AB-771", "AB-771 · 210 bar"), ("AB-7710", "AB-7710 · 210 bar")]}

S = {"step": 0, "pos": 0, "items": {}, "extra": False, "type": "alt", "bidder": {}, "cond": {}, "decl": {},
     "tan": None, "tan_no": 0, "done": None, "alert": "", "log": []}


def blank():
    return {"dia": "", "len": "", "seal": "", "art": "", "qty": "", "price": "", "base": "", "sur": "", "pack": "",
            "bonus": "", "weeks": "", "skipped": False, "confirmed": 0}


def positions():
    return ORDER + (["1.4"] if S["extra"] else [])


def sel(name, label, options, value, disabled=False):
    opts = '<option value="">Please choose</option>' + "".join(
        f'<option value="{v}"{" selected" if v == value else ""}>{html.escape(t)}</option>' for v, t in options)
    return f'<label>{label}<select name="{name}"{" disabled" if disabled else ""}>{opts}</select></label>'


def inp(name, label, value):
    return f'<label>{label} <input name="{name}" value="{html.escape(value)}"></label>'


def page_body():
    st = S["step"]
    if S["done"]:
        return f"<h2>Bid received</h2><p>Your bid was submitted. Receipt {S['done']}.</p>"
    if st == 0:
        b = S["bidder"]
        return ("<h2>Bidder details</h2>" + inp("company", "Company", b.get("company", "")) + inp("vat", "VAT number", b.get("vat", ""))
                + inp("email", "Contact e-mail", b.get("email", "")) + '<button name="a" value="next">Continue</button>')
    if st == 1:
        return ("<h2>Type of offer</h2>" + sel("type", "Offer type", [("alt", "Alternative offer"), ("main", "Main offer"),
                                                                     ("none", "Declaration of no offer")], S["type"])
