    return (f"<h2>Review and sign</h2>{alert}<p>Offer type: {S['type']}; discount {S['cond'].get('discount')}; net {S['cond'].get('total')}</p>"
            f"<table>{rows}</table>{msg}<button name='a' value='tan'>Request TAN</button>" + inp("tan", "Signing TAN", "")
            + "<button name='a' value='submit' id=sub>Submit bid bindingly</button> <button name='a' value='back'>Back</button>"
            "<script>document.getElementById('sub').form.addEventListener('submit',e=>{if(e.submitter&&e.submitter.value==='submit'&&!confirm('Submit bindingly?'))e.preventDefault();});</script>")


def handle(form):
    a = form.get("a", "")
    st = S["step"]
    S["log"].append({"step": st, "a": a, "form": form})
    if a == "back":
        S["step"] = max(0, st - 1)
        return
    if st == 0:
        S["bidder"] = {k: form.get(k, "") for k in ("company", "vat", "email")}
        S["step"] = 1
    elif st == 1:
        S["type"] = form.get("type", S["type"])
        S["step"] = 2
        S["pos"] = 0
    elif st == 2:
        pid = positions()[S["pos"]]
        it = S["items"].setdefault(pid, blank())
        for k in ("dia", "len", "seal", "art", "qty", "price", "base", "sur", "pack", "bonus", "weeks"):
            if k in form:
                it[k] = form[k]
        if a == "apply":
            # each level opens only the next one; a changed upper level resets lower ones
            lv = it["confirmed"]
            if it["dia"] and lv == 0:
                it["confirmed"] = 1
            elif lv == 1 and it["len"]:
                it["confirmed"] = 2
            elif lv == 2 and it["seal"]:
                it["confirmed"] = 3
            return
        if a == "add":
            S["extra"] = True
            return
        if a == "remove":
            S["extra"] = False
            S["items"].pop("1.4", None)
            return
        if a == "skip":
            it["skipped"] = True
        elif a == "next":
            if not (it["art"] and it["qty"] and it["price"] and it["weeks"]):
                S["alert"] = "Please complete the item or leave it out."
                return
            it["skipped"] = False
        S["pos"] += 1
        if S["pos"] >= len(positions()):
            S["step"] = 3
    elif st == 3:
        S["cond"] = {"discount": form.get("discount", ""), "total": form.get("total", "")}
        S["step"] = 4
    elif st == 4:
        S["decl"] = {"ack": "ack" in form, "terms": "terms" in form}
        S["step"] = 5
    elif st == 5:
        if a == "tan":
            S["tan_no"] += 1
            S["tan"] = f"{random.randint(100000, 999999)}"
        elif a == "submit":
            if S["tan"] and form.get("tan", "").strip() == S["tan"]:
                S["done"] = f"R-{S['tan_no']}"
            else:
                S["alert"] = "TAN invalid."


class H(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def send(self, body, ctype="text/html; charset=utf-8"):
        data = body.encode()
        self.send_response(200)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path == "/_tan":
            return self.send(json.dumps({"tan": S["tan"], "no": S["tan_no"]}), "application/json")
        if self.path == "/_state":
            return self.send(json.dumps({k: S[k] for k in ("items", "extra", "type", "bidder", "cond", "decl", "done")}),
                             "application/json")
        body = page_body()
        self.send(f"<!doctype html><html><head><title>Bid wizard</title></head><body><h1>Submit bid</h1>"
                  f"<form method=post action='/bid'>{body}</form></body></html>")

    def do_POST(self):
        n = int(self.headers.get("Content-Length", 0))
        form = {k: v[0] for k, v in parse_qs(self.rfile.read(n).decode(), keep_blank_values=True).items()}
        handle(form)
        self.send_response(303)
        self.send_header("Location", "/bid")
        self.end_headers()


HTTPServer(("127.0.0.1", int(sys.argv[1])), H).serve_forever()

